function ftPosStep(inst, stepIndex) {
    var wrap = document.getElementById("ft-pos-wrap-" + inst);
    if (!wrap) return;
    var panelMap = JSON.parse(wrap.getAttribute("data-ftpanels"));
    wrap.querySelectorAll(".ft-panel").forEach(function(p){ p.classList.remove("ft-active"); });
    var leagueSel = document.getElementById("ft-pos-league-" + inst);
    leagueSel.innerHTML = "";
    var panels = panelMap[stepIndex];
    for (var i = 0; i < panels.length; i++) {
        var opt = document.createElement("option");
        opt.value = panels[i].pid;
        opt.text  = panels[i].label;
        leagueSel.appendChild(opt);
    }
    if (panels.length > 0) {
        var first = document.getElementById(panels[0].pid);
        if (first) first.classList.add("ft-active");
    }
}

